sys_script.script:
(function executeRule(current, previous) {
  var status = (current.application_status + '').toLowerCase();
  var prevStatus = (previous.application_status + '').toLowerCase();
  if (status === 'approved' && prevStatus !== 'approved') {
    var docGr = new GlideRecord('x_2200409_schola_1_scholarship_documents');
    docGr.addQuery('application', current.getUniqueValue());
    docGr.query();
    var totalDocs = docGr.getRowCount();
    if (totalDocs === 0) {
      gs.addErrorMessage('Cannot approve application: No supporting documents found. At least one verified document is required.');
      current.setAbortAction(true);
      return;
    }
    while (docGr.next()) {
      var verStatus = (docGr.verification_status + '').toLowerCase();
      if (verStatus === 'pending' || verStatus === 'rejected') {
        gs.addErrorMessage('Cannot approve application: Supporting documents are not fully verified (Status: ' + verStatus + ').');
        current.setAbortAction(true);
        return;
      }
    }
  }
})(current, previous);
